import secrets
from datetime import timedelta

from odoo import api, fields, models

INVITE_VALIDITY_DAYS = 14


class BelfryInvite(models.Model):
    """Single-use, expiring invite link generated by a steward."""

    _name = 'belfry.invite'
    _description = "Belfry invite"
    _order = 'id desc'

    token = fields.Char(
        required=True,
        copy=False,
        readonly=True,
        index=True,
        default=lambda self: secrets.token_urlsafe(32),
    )
    steward_id = fields.Many2one(
        'res.users',
        string="Steward",
        required=True,
        index=True,
        default=lambda self: self.env.user,
        help="Who admitted the participant.",
    )
    expires_at = fields.Datetime(
        required=True,
        default=lambda self: fields.Datetime.now() + timedelta(days=INVITE_VALIDITY_DAYS),
    )
    state = fields.Selection(
        [
            ('open', "Open"),
            ('used', "Used"),
            ('expired', "Expired"),
            ('revoked', "Revoked"),
        ],
        default='open',
        required=True,
        index=True,
        copy=False,
    )
    used_by_partner_id = fields.Many2one('res.partner', string="Used by", readonly=True, copy=False)
    pass_id = fields.Many2one('belfry.pass', string="Pass", readonly=True, copy=False)
    note = fields.Char(help="Free text for the steward, e.g. who the invite is meant for.")
    url = fields.Char(compute='_compute_url', string="Invite link")

    _token_unique = models.Constraint(
        'UNIQUE(token)',
        'Invite tokens must be unique.',
    )

    @api.depends('token')
    def _compute_url(self):
        base_url = self.get_base_url()
        for invite in self:
            invite.url = "%s/belfry/invite/%s" % (base_url, invite.token)

    def _compute_display_name(self):
        for invite in self:
            invite.display_name = "Invite #%s (%s)" % (invite.id, invite.steward_id.name or "?")

    def _belfry_usability_error(self):
        """Return ``False`` when the invite can be used now, else one of
        ``used`` / ``expired`` / ``revoked``. An open invite past its expiry is moved to
        ``expired`` on the way.
        """
        self.ensure_one()
        if self.state == 'open' and self.expires_at and self.expires_at < fields.Datetime.now():
            self.sudo().write({'state': 'expired'})
        if self.state == 'open':
            return False
        return self.state

    def action_revoke(self):
        self.filtered(lambda i: i.state == 'open').write({'state': 'revoked'})

    def action_mark_expired(self):
        self.filtered(lambda i: i.state == 'open' and i.expires_at < fields.Datetime.now()).write({'state': 'expired'})
